CREATE TYPE "Sentiment" AS ENUM ('POSITIVE', 'NEGATIVE', 'NEUTRAL');
CREATE TYPE "RunStatus" AS ENUM ('RUNNING', 'COMPLETED', 'PARTIALLY_COMPLETED', 'FAILED', 'RATE_LIMITED', 'USAGE_LIMIT_REACHED');
CREATE TABLE "Model" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "slug" TEXT NOT NULL UNIQUE, "vendor" TEXT NOT NULL, "description" TEXT NOT NULL, "aliases" TEXT[] NOT NULL, "searchQuery" TEXT NOT NULL, "visual" TEXT, "isEnabled" BOOLEAN NOT NULL DEFAULT true, "displayOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "XPost" ("id" TEXT PRIMARY KEY, "xPostId" TEXT NOT NULL UNIQUE, "authorXId" TEXT NOT NULL, "authorUsername" TEXT NOT NULL, "authorName" TEXT NOT NULL, "text" TEXT NOT NULL, "language" TEXT NOT NULL DEFAULT 'en', "publishedAt" TIMESTAMP(3) NOT NULL, "conversationId" TEXT, "likeCount" INTEGER NOT NULL DEFAULT 0, "replyCount" INTEGER NOT NULL DEFAULT 0, "repostCount" INTEGER NOT NULL DEFAULT 0, "quoteCount" INTEGER NOT NULL DEFAULT 0, "viewCount" INTEGER, "rawPayload" JSONB, "isDemo" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ModelMention" ("id" TEXT PRIMARY KEY, "postId" TEXT NOT NULL REFERENCES "XPost"("id") ON DELETE CASCADE, "modelId" TEXT NOT NULL REFERENCES "Model"("id") ON DELETE CASCADE, "sentiment" "Sentiment" NOT NULL, "sentimentScore" DOUBLE PRECISION NOT NULL, "confidence" DOUBLE PRECISION NOT NULL, "explanation" TEXT NOT NULL, "strengths" TEXT[] NOT NULL, "weaknesses" TEXT[] NOT NULL, "analysisProvider" TEXT NOT NULL, "analysisVersion" TEXT NOT NULL, "analyzedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE ("postId", "modelId"));
CREATE TABLE "Topic" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "slug" TEXT NOT NULL UNIQUE);
CREATE TABLE "MentionTopic" ("mentionId" TEXT NOT NULL REFERENCES "ModelMention"("id") ON DELETE CASCADE, "topicId" TEXT NOT NULL REFERENCES "Topic"("id") ON DELETE CASCADE, "sentimentScore" DOUBLE PRECISION NOT NULL, PRIMARY KEY ("mentionId", "topicId"));
CREATE TABLE "IngestionRun" ("id" TEXT PRIMARY KEY, "status" "RunStatus" NOT NULL DEFAULT 'RUNNING', "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), "durationMs" INTEGER, "errorMessage" TEXT, "metadata" JSONB);
CREATE TABLE "IngestionModelResult" ("id" TEXT PRIMARY KEY, "ingestionRunId" TEXT NOT NULL REFERENCES "IngestionRun"("id") ON DELETE CASCADE, "modelId" TEXT NOT NULL REFERENCES "Model"("id"), "status" "RunStatus" NOT NULL DEFAULT 'RUNNING', "pagesRequested" INTEGER NOT NULL DEFAULT 0, "postsFetched" INTEGER NOT NULL DEFAULT 0, "postsExamined" INTEGER NOT NULL DEFAULT 0, "existingPosts" INTEGER NOT NULL DEFAULT 0, "existingAssociations" INTEGER NOT NULL DEFAULT 0, "newPostsInserted" INTEGER NOT NULL DEFAULT 0, "newAssociationsInserted" INTEGER NOT NULL DEFAULT 0, "rejectedPosts" INTEGER NOT NULL DEFAULT 0, "analysesCompleted" INTEGER NOT NULL DEFAULT 0, "targetCount" INTEGER NOT NULL DEFAULT 25, "targetReached" BOOLEAN NOT NULL DEFAULT false, "rateLimitStatus" TEXT, "errorMessage" TEXT, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), "durationMs" INTEGER, UNIQUE ("ingestionRunId", "modelId"));
CREATE TABLE "JobLock" ("name" TEXT PRIMARY KEY, "ownerId" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "XPost_publishedAt_idx" ON "XPost"("publishedAt");
CREATE INDEX "XPost_likeCount_idx" ON "XPost"("likeCount");
CREATE INDEX "XPost_repostCount_idx" ON "XPost"("repostCount");
CREATE INDEX "XPost_replyCount_idx" ON "XPost"("replyCount");
CREATE INDEX "XPost_viewCount_idx" ON "XPost"("viewCount");
CREATE INDEX "ModelMention_modelId_idx" ON "ModelMention"("modelId");
CREATE INDEX "ModelMention_sentiment_idx" ON "ModelMention"("sentiment");
CREATE INDEX "ModelMention_modelId_sentiment_idx" ON "ModelMention"("modelId", "sentiment");
CREATE INDEX "IngestionRun_status_idx" ON "IngestionRun"("status");
CREATE INDEX "IngestionRun_startedAt_idx" ON "IngestionRun"("startedAt");
CREATE INDEX "IngestionModelResult_status_idx" ON "IngestionModelResult"("status");
